  { id: 'recidivism', href: '/daep/reports/recidivism' }, // New drill-down
];

// 3. ADMIN_ROLES constant already defined:
const ADMIN_ROLES = ['daep_admin_l1', 'daep_admin_l2', 'super_admin'];

// 4. HEADER section - Add campus filter:
<motion.div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
  <div>
    <h1>Good morning!</h1>
    <p>Here's what needs your attention today</p>
  </div>
  {/* ADD: <CampusFilter /> here */}
  <PreviewQuickActions />
</motion.div>

// KPI card hover animation
export const kpiCardHover = {
  rest: {
    y: 0,
    boxShadow: '0 1px 3px 0 rgb(0 0 0 / 0.1), 0 1px 2px -1px rgb(0 0 0 / 0.1)',
  },
  hover: {
    y: -2,
    boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1)',
    transition: { duration: 0.2, ease: 'easeOut' },
  },
};

// Number count-up config
export const countUpConfig = {
  duration: 1.2,
  ease: [0.16, 1, 0.3, 1],
};

// List item entrance
export const listItemEntrance = {
  initial: { opacity: 0, y: 15 },
  animate: { opacity: 1, y: 0, transition: { duration: 0.35, ease: 'easeOut' } },
};

// Role type definition
export type UserRole =
  | 'viewer' | 'campus_admin' | 'district_admin' | 'super_admin'
  | 'daep_admin_l1' | 'daep_admin_l2' | 'daep_staff'
  | 'parent' | 'student' | 'counselor';

// Role hierarchy (higher = more permissions)
export const ROLE_HIERARCHY: Record<UserRole, number> = {
  super_admin: 100,
  district_admin: 90,
  daep_admin_l1: 80,
  campus_admin: 70,
  daep_admin_l2: 60,
  daep_staff: 50,
  counselor: 40,
  viewer: 30,
  parent: 20,
  student: 10,
};

// Permission check
export function hasPermission(userRole: UserRole, requiredRole: UserRole): boolean {
  return ROLE_HIERARCHY[userRole] >= ROLE_HIERARCHY[requiredRole];
}

// DAEP-specific roles
export const DAEP_ROLES: UserRole[] = ['daep_admin_l1', 'daep_admin_l2', 'daep_staff'];

