useEffect(() => {
  async function checkAuth() {
    const profile = await getUserProfile(user.id);
    const role = profile?.role || 'viewer';
    if (ADMIN_ROLES.includes(role)) {
      setIsAuthorized(true);
    } else {
      router.push('/daep');
    }
  }
  checkAuth();
}, [user, isLoaded, router]);

