template.code:
'use client';

import { useRouter, usePathname, useSearchParams } from 'next/navigation';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Building2 } from 'lucide-react';

interface Campus {
  id: string;
  name: string;
}

interface CampusFilterProps {
  campuses: Campus[];
  // If only 1 campus, component returns null (auto-hide)
}

export function CampusFilter({ campuses }: CampusFilterProps) {
  const router = useRouter();
  const pathname = usePathname();
  const searchParams = useSearchParams();

  // Auto-hide for single-campus tenants
  if (campuses.length <= 1) {
    return null;
  }

  const currentCampus = searchParams.get('campus') || 'all';

  const handleChange = (value: string) => {
    const params = new URLSearchParams(searchParams.toString());
    if (value === 'all') {
      params.delete('campus');
    } else {
      params.set('campus', value);
    }
    router.push(`${pathname}?${params.toString()}`);
  };

  return (
    <Select value={currentCampus} onValueChange={handleChange}>
      <SelectTrigger className="w-[200px]">
        <Building2 className="h-4 w-4 mr-2" />
        <SelectValue placeholder="All Campuses" />
      </SelectTrigger>
      <SelectContent>
        <SelectItem value="all">All Campuses</SelectItem>
        {campuses.map((campus) => (
          <SelectItem key={campus.id} value={campus.id}>
            {campus.name}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}

import { redirect } from 'next/navigation';
import { currentUser } from '@clerk/nextjs/server';
import { getUserProfile } from '@/app/actions/users';
import { getRecidivismBreakdown } from '@/app/actions/daep/dashboard';
import { DrillDownHeader } from '../../dashboard-preview/components/drill-down-header';
import { DrillDownBreadcrumb } from '../../dashboard-preview/components/drill-down-breadcrumb';

// Roles allowed to access this page
const ALLOWED_ROLES = ['super_admin', 'district_admin', 'daep_admin_l1', 'daep_admin_l2'];

interface PageProps {
  searchParams: { campus?: string };
}

export default async function RecidivismPage({ searchParams }: PageProps) {
  // Role check
  const user = await currentUser();
  if (!user) redirect('/daep');

  const profile = await getUserProfile(user.id);
  if (!profile || !ALLOWED_ROLES.includes(profile.role)) {
    redirect('/daep'); // Redirect non-authorized users
  }

  // Fetch data
  const campusId = searchParams.campus;
  const data = await getRecidivismBreakdown(campusId);

  return (
    <div className="space-y-6">
      <DrillDownBreadcrumb
        items={[
          { label: 'Dashboard', href: '/daep/dashboard-preview' },
          { label: 'Recidivism Rate' }
        ]}
      />

      <DrillDownHeader
        title="Recidivism Rate"
        subtitle={`${data.rate}% (${data.returningCount} of ${data.totalCompleted} returned)`}
        campusId={campusId}
      />

      {/* Charts: By Offense, Time to Return */}
      {/* Table: Returning Students with profile links */}
    </div>
  );
}
